-- Import 126 spreadsheet customers into บริษัท เอส.อาร์. แสตมป์ปิ้ง พลัส จำกัด (OVERWRITE)
-- Match by tax_id or case-insensitive name: UPDATE name/tax/address/note + reactivate,
-- preserve existing code (backfill when NULL). No match: INSERT with next free C-###.
DO $$
DECLARE
  v_user_id uuid;
  v_next int := 1;
  r record;
  v_eid uuid;
  v_ecode text;
  v_code text;
  v_inserted int := 0;
  v_updated int := 0;
  v_backfilled int := 0;
BEGIN
  SELECT cp.user_id INTO v_user_id FROM public.client_profiles cp WHERE cp.company_name_th = 'บริษัท เอส.อาร์. แสตมป์ปิ้ง พลัส จำกัด' LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'workspace not found: %', 'บริษัท เอส.อาร์. แสตมป์ปิ้ง พลัส จำกัด';
  END IF;
  SELECT COALESCE(MAX((regexp_match(code, '^C-(\d+)$'))[1]::int), 0) + 1 INTO v_next
    FROM public.customers WHERE user_id = v_user_id AND code ~ '^C-[0-9]+$';
  CREATE TEMP TABLE _stg(seq int PRIMARY KEY, name text NOT NULL, tax_id text NOT NULL, address text, note text) ON COMMIT DROP;
