  FOR r IN SELECT * FROM _stg ORDER BY seq LOOP
    SELECT c.id, c.code INTO v_eid, v_ecode FROM public.customers c WHERE c.user_id = v_user_id AND (c.tax_id = r.tax_id OR lower(c.name) = lower(r.name)) LIMIT 1;
    IF FOUND THEN
      UPDATE public.customers SET name = r.name, tax_id = r.tax_id, address = r.address, note = r.note, is_active = true WHERE id = v_eid;
      IF v_ecode IS NULL THEN
        v_code := 'C-' || lpad(v_next::text, 3, '0'); v_next := v_next + 1;
        UPDATE public.customers SET code = v_code WHERE id = v_eid;
        v_backfilled := v_backfilled + 1;
      END IF;
      v_updated := v_updated + 1;
    ELSE
      v_code := 'C-' || lpad(v_next::text, 3, '0'); v_next := v_next + 1;
      INSERT INTO public.customers(user_id,name,tax_id,address,note,code,is_active) VALUES (v_user_id,r.name,r.tax_id,r.address,r.note,v_code,true);
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'customers import (overwrite): inserted=%, updated=%, codes_backfilled=%', v_inserted, v_updated, v_backfilled;
END $$;
